// ============================ SETTINGS (safe to change) ============================
// Pages allowed to use this tool (exact origins: https:// + domain, no path).
const ALLOWED_ORIGINS = ['https://sehnounberoual.systeme.io', 'https://systeme.io', 'https://www.systeme.io'];
// Cloudflare Turnstile Secret Key. Leave '' to switch the human check off.
const TURNSTILE_SECRET = '';
// Signs the writing pass. Any long random text; '' = generated automatically once.
const PASS_SECRET = '';
const DAILY_LIMIT = 1000;        // lead magnets (outlines) per day, all visitors together (UTC day)
const OUTLINES_PER_HOUR = 6;     // per visitor
const SECTIONS_PER_HOUR = 80;    // per visitor (an ebook is up to 9 sections, plus rewrites)
const PASS_HOURS = 24;           // how long a writing pass stays valid
// ===================================================================================

// Each webhook (outline / section / pass) tags its request with `action` before this node.
const wh = $input.first().json;
const headers = wh.headers || {};
const body = wh.body && typeof wh.body === 'object' ? wh.body : {};
const action = String(wh.action || '').toLowerCase();

function stop(statusCode, code, message, extra) {
  return [{ json: Object.assign({ ok: false, statusCode: statusCode, response: { ok: false, code: code, message: message } }, extra || {}) }];
}

// ---------- tiny SHA-256 / HMAC (no external modules needed) ----------
function sha256(bytes) {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length, withPad = ((l + 9 + 63) >> 6) << 6;
  const m = new Uint8Array(withPad); m.set(bytes); m[l] = 0x80;
  const bits = l * 8; m[withPad - 4] = bits >>> 24; m[withPad - 3] = (bits >>> 16) & 255; m[withPad - 2] = (bits >>> 8) & 255; m[withPad - 1] = bits & 255;
  m[withPad - 5] = Math.floor(l / 0x20000000) & 255;
  const w = new Array(64);
  for (let i = 0; i < withPad; i += 64) {
    for (let t = 0; t < 16; t++) w[t] = (m[i + 4 * t] << 24) | (m[i + 4 * t + 1] << 16) | (m[i + 4 * t + 2] << 8) | m[i + 4 * t + 3];
    for (let t = 16; t < 64; t++) {
      const a = w[t - 15], b = w[t - 2];
      const s0 = ((a >>> 7) | (a << 25)) ^ ((a >>> 18) | (a << 14)) ^ (a >>> 3);
      const s1 = ((b >>> 17) | (b << 15)) ^ ((b >>> 19) | (b << 13)) ^ (b >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + w[t]) | 0;
      const S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
      const t2 = (S0 + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  const out = new Uint8Array(32);
  H.forEach((v, i) => { out[4 * i] = v >>> 24; out[4 * i + 1] = (v >>> 16) & 255; out[4 * i + 2] = (v >>> 8) & 255; out[4 * i + 3] = v & 255; });
  return out;
}
function utf8(s) { return Buffer.from(String(s), 'utf8'); }
function hex(b) { return Array.from(b, x => x.toString(16).padStart(2, '0')).join(''); }
function hmac(key, msg) {
  let k = utf8(key); if (k.length > 64) k = sha256(k);
  const ip = new Uint8Array(64), op = new Uint8Array(64);
  for (let i = 0; i < 64; i++) { ip[i] = (k[i] || 0) ^ 0x36; op[i] = (k[i] || 0) ^ 0x5c; }
  const mb = utf8(msg);
  const inner = new Uint8Array(64 + mb.length); inner.set(ip); inner.set(mb, 64);
  const ih = sha256(inner);
  const outer = new Uint8Array(96); outer.set(op); outer.set(ih, 64);
  return hex(sha256(outer));
}
function randomHex(n) {
  const b = new Uint8Array(n);
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) crypto.getRandomValues(b);
  else for (let i = 0; i < n; i++) b[i] = Math.floor(Math.random() * 256);
  return hex(b);
}
function b64url(s) { return Buffer.from(s, 'utf8').toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_'); }
function unb64url(s) { return Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8'); }
function safeEqual(a, b) { if (a.length !== b.length) return false; let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0; }

// ---------- storage (workflow static data: kept between runs of the active workflow) ----------
const sd = $getWorkflowStaticData('global');
if (!sd.secret) sd.secret = randomHex(32);
const secret = PASS_SECRET || sd.secret;
const now = new Date();
const day = now.toISOString().slice(0, 10), hour = now.toISOString().slice(0, 13);
if (sd.day !== day) { sd.day = day; sd.outlines = 0; sd.sections = 0; }
if (sd.hour !== hour) { sd.hour = hour; sd.visitors = {}; }
const minutesLeft = 60 - now.getUTCMinutes();

function makePass() {
  const payload = b64url(JSON.stringify({ e: Math.floor(Date.now() / 1000) + PASS_HOURS * 3600, n: randomHex(6) }));
  return payload + '.' + hmac(secret, payload).slice(0, 40);
}
function passValid(p) {
  if (typeof p !== 'string' || p.length > 300 || p.indexOf('.') < 1) return false;
  const [payload, sig] = p.split('.');
  if (!safeEqual(sig || '', hmac(secret, payload).slice(0, 40))) return false;
  try { const d = JSON.parse(unb64url(payload)); return typeof d.e === 'number' && d.e > Date.now() / 1000; } catch (e) { return false; }
}

// ---------- checks ----------
if (action !== 'outline' && action !== 'section' && action !== 'pass') return stop(404, 'not_found', 'Unknown address.');

const origin = String(headers.origin || '');
if (ALLOWED_ORIGINS.length && ALLOWED_ORIGINS.indexOf(origin) === -1) {
  return stop(403, 'forbidden_origin', 'This tool can only be used from its own page.');
}

// Visitor key: hashed IP (never stored in clear). No IP found = no per-visitor limit.
const ip = String(headers['cf-connecting-ip'] || String(headers['x-forwarded-for'] || '').split(',')[0] || headers['x-real-ip'] || '').trim();
const vkey = ip ? hmac(secret, 'ip:' + ip).slice(0, 16) : '';
const visitor = vkey ? (sd.visitors[vkey] = sd.visitors[vkey] || { o: 0, s: 0 }) : { o: 0, s: 0 };

const token = typeof body.turnstile === 'string' ? body.turnstile.slice(0, 2048) : '';
let verify = false, newPass = '';

if (action === 'outline') {
  if (sd.outlines >= DAILY_LIMIT) return stop(503, 'daily_limit', 'The generator is very busy today. Please come back tomorrow.');
  if (visitor.o >= OUTLINES_PER_HOUR) return stop(429, 'rate_limited', 'You have created several lead magnets in a short time. Please try again in about ' + minutesLeft + ' minutes.');
  if (TURNSTILE_SECRET) {
    if (!token) return stop(403, 'verify_required', 'Please confirm you are human, then try again.');
    verify = true;
  }
  visitor.o++; sd.outlines++;
  newPass = makePass();
} else if (action === 'pass') {
  // Fresh writing pass after the old one expired. No AI call.
  if (visitor.o >= OUTLINES_PER_HOUR * 3) return stop(429, 'rate_limited', 'Too many attempts. Please try again in about ' + minutesLeft + ' minutes.');
  if (TURNSTILE_SECRET) {
    if (!token) return stop(403, 'verify_required', 'Please confirm you are human, then try again.');
    verify = true;
  }
  visitor.o += 0.34;
  newPass = makePass();
} else {
  if (sd.sections >= DAILY_LIMIT * 12) return stop(503, 'daily_limit', 'The generator is very busy today. Please come back tomorrow.');
  if (visitor.s >= SECTIONS_PER_HOUR) return stop(429, 'rate_limited', 'You have written a lot of sections in a short time. Please try again in about ' + minutesLeft + ' minutes.');
  if (!passValid(body.pass)) {
    if (TURNSTILE_SECRET) {
      if (!token) return stop(403, 'verify_required', 'For your security, please confirm you are human to keep writing.');
      verify = true;
    }
    newPass = makePass();
  }
  visitor.s++; sd.sections++;
}

return [{ json: { ok: true, statusCode: 200, action: action, verify: verify, newPass: newPass, body: body,
  turnstileBody: verify ? { secret: TURNSTILE_SECRET, response: token, remoteip: ip || undefined } : null,
  allowedHosts: ALLOWED_ORIGINS.map(o => o.replace(/^https?:\/\//, '')) } }];

// Checks Cloudflare's answer to the human check.
const g = $('Guard').first().json;
const r = $input.first().json || {};
const hostOk = !r.hostname || g.allowedHosts.indexOf(r.hostname) !== -1;
if (!r.success || !hostOk) {
  return [{ json: { ok: false, statusCode: 403, response: { ok: false, code: 'verify_failed', message: 'We could not confirm you are human. Please try again.' } } }];
}
return [{ json: { ok: true, action: g.action } }];

// Answer for /pass: just the fresh writing pass.
const g = $('Guard').first().json;
return [{ json: { statusCode: 200, response: { ok: true, pass: g.newPass } } }];

// ===================== SETTINGS (safe to change) =====================
const PROMPT_VERSION = 'v3';          // which prompt files to use: outline.<format>.v3.md
const MODEL = 'gpt-4.1-mini';         // OpenAI model used for the outline
const REPO_RAW = 'https://raw.githubusercontent.com/mysteriouslyscentedtyrant/lead-magnet-generator/main';
// =====================================================================

const FORMATS = ['ebook', 'guide', 'checklist'];
const TONES = ['friendly', 'professional', 'bold', 'inspiring', 'conversational'];
const LENGTHS = ['short', 'standard', 'detailed'];

const body = $('Guard').first().json.body || {};
const errors = [];

// Removes invisible/control characters, angle brackets and {{ }} so user text
// can't break out of the <user_input> tags or inject placeholders.
function clean(value) {
  if (typeof value !== 'string') return '';
  return value
    .normalize('NFKC')
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u2069\uFEFF]/g, ' ')
    .replace(/[<>]/g, ' ')
    .replace(/\{\{|\}\}/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function text(field, label, min, max) {
  const v = clean(body[field]);
  if (v.length < min) errors.push(`${label} must be at least ${min} characters.`);
  else if (v.length > max) errors.push(`${label} must be ${max} characters or less.`);
  return v;
}

function choice(field, label, allowed, fallback) {
  const raw = body[field];
  if (raw === undefined || raw === null || raw === '') {
    if (fallback !== undefined) return fallback;
    errors.push(`${label} is required.`);
    return '';
  }
  const v = String(raw).trim().toLowerCase();
  if (!allowed.includes(v)) {
    errors.push(`${label} must be one of: ${allowed.join(', ')}.`);
    return '';
  }
  return v;
}

const format = choice('format', 'Format', FORMATS);
const topic = text('topic', 'Topic', 3, 200);
const audience = text('audience', 'Audience', 3, 400);
const offer = text('offer', 'Offer', 0, 300);   // optional
const tone = choice('tone', 'Tone', TONES, 'friendly');
const length = choice('length', 'Length', LENGTHS, 'standard');

let language = clean(body.language || '') || 'English';
if (!/^[\p{L} ()-]{2,30}$/u.test(language)) {
  errors.push('Language must be a language name such as English or French.');
}

if (errors.length) {
  return [{
    json: {
      ok: false, statusCode: 400,
      response: { ok: false, code: 'invalid_input', message: errors.join(' ') },
    },
  }];
}

return [{
  json: {
    ok: true,
    input: { format, topic, audience, offer, tone, length, language },
    model: MODEL,
    promptVersion: PROMPT_VERSION,
    promptUrl: `${REPO_RAW}/prompts/outline.${format}.${PROMPT_VERSION}.md`,
    schemaUrl: `${REPO_RAW}/schema/outline.response.schema.json`,
  },
}];

// Builds the OpenAI request from the prompt file and response schema loaded from GitHub.
const settings = $('Validate outline input').first().json;
const input = settings.input;
const promptText = String($('Load outline prompt').first().json.data || '').replace(/\r\n/g, '\n');
const schemaText = $('Load outline schema').first().json.data;

// Split the prompt file into its SYSTEM and USER parts.
const sysMarker = '===SYSTEM===';
const userMarker = '===USER===';
const sysAt = promptText.indexOf(sysMarker);
const userAt = promptText.indexOf(userMarker);
if (sysAt === -1 || userAt === -1 || userAt < sysAt) {
  throw new Error('Prompt file is missing the ===SYSTEM=== or ===USER=== marker: ' + settings.promptUrl);
}
const system = promptText.slice(sysAt + sysMarker.length, userAt).trim();
const userTemplate = promptText.slice(userAt + userMarker.length).trim();

// Fill {{placeholders}} in ONE pass, so text typed by a user is never re-read as a placeholder.
const vars = { ...input, offer: input.offer || 'Not provided' };
const user = userTemplate.replace(/\{\{(\w+)\}\}/g, (match, key) => {
  if (!(key in vars)) throw new Error('Prompt uses an unknown placeholder: ' + match);
  return vars[key];
});

let responseSchema;
try {
  responseSchema = typeof schemaText === 'string' ? JSON.parse(schemaText) : schemaText;
} catch (e) {
  throw new Error('Response schema is not valid JSON: ' + settings.schemaUrl);
}

return [{
  json: {
    requestBody: {
      model: settings.model,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      response_format: { type: 'json_schema', json_schema: responseSchema },
      max_completion_tokens: 3000,
    },
  },
}];

// Checks the AI answer and turns it into the document shape used by the frontend.
// Any problem throws an error -> the workflow answers with a generic "please try again".
const settings = $('Validate outline input').first().json;
const input = settings.input;
const res = $input.first().json;

const choice = res.choices && res.choices[0];
const message = choice && choice.message;
if (!message) throw new Error('OpenAI returned no message: ' + JSON.stringify(res).slice(0, 500));
if (choice.finish_reason === 'length') throw new Error('Outline was cut off (max_completion_tokens too low).');

function rejected(reason) {
  return [{
    json: {
      response: {
        ok: false,
        code: 'rejected',
        message: reason || "We can't create a lead magnet on this topic. Please try a different one.",
      },
    },
  }];
}

if (message.refusal) return rejected();

let data;
try {
  data = JSON.parse(message.content);
} catch (e) {
  throw new Error('AI answer is not valid JSON: ' + String(message.content).slice(0, 500));
}

// ---------- text helpers ----------
function tidy(value) {
  return String(value == null ? '' : value)
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u2069\uFEFF]/g, ' ')
    .replace(/\*\*|__|`/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}
function cut(value, max) {
  const v = tidy(value);
  if (v.length <= max) return v;
  const short = v.slice(0, max);
  const space = short.lastIndexOf(' ');
  return (space > max * 0.6 ? short.slice(0, space) : short).replace(/[\s,;:.-]+$/, '');
}
function heading(value) {
  return cut(String(value || '').replace(/^\s*(#+|\d+[.)](?=\s)|[-*\u2022](?=\s))\s*/, ''), 90);
}

if (data.status === 'rejected') return rejected(cut(data.reason, 200));
if (data.status !== 'ok') throw new Error('Unexpected status: ' + data.status);

// ---------- structure rules per format ----------
const RULES = {
  ebook:     { first: ['intro'],   middle: 'chapter', last: ['conclusion'],            min: 4, max: 7 },
  guide:     { first: ['problem'], middle: 'step',    last: ['mistakes', 'next_step'], min: 3, max: 9 },
  checklist: { first: [],          middle: 'group',   last: [],                        min: 3, max: 5 },
};
const rule = RULES[input.format];
const raw = Array.isArray(data.sections) ? data.sections : [];
const types = raw.map(s => s && s.type);
const middleCount = types.length - rule.first.length - rule.last.length;
const expected = [...rule.first, ...Array(Math.max(middleCount, 0)).fill(rule.middle), ...rule.last];

if (middleCount < rule.min || middleCount > rule.max || types.join() !== expected.join()) {
  throw new Error(`Outline structure is wrong for ${input.format}: [${types.join(', ')}]`);
}

const sections = raw.map((s, i) => ({
  id: 's' + (i + 1),
  type: s.type,
  heading: heading(s.heading),
  goal: cut(s.goal, 200),
  keyPoints: (Array.isArray(s.keyPoints) ? s.keyPoints : [])
    .map(k => cut(String(k).replace(/^\s*(\d+[.)](?=\s)|[-*\u2022](?=\s)|\[ ?\])\s*/, ''), 160))
    .filter(Boolean)
    .slice(0, 8),
  status: 'outlined',
  blocks: [],
}));

if (sections.some(s => s.heading.length < 2)) throw new Error('A section heading is empty or too short.');

// A checklist must fit on one page: keep at most 20 items in total.
if (input.format === 'checklist') {
  let total = sections.reduce((n, s) => n + s.keyPoints.length, 0);
  while (total > 20) {
    const biggest = sections.reduce((a, b) => (b.keyPoints.length > a.keyPoints.length ? b : a));
    biggest.keyPoints.pop();
    total--;
  }
}

const title = cut(data.title, 90);
if (!title) throw new Error('Outline has no title.');

const cta = data.cta || {};

return [{
  json: {
    response: {
      ok: true,
      // The frontend adds "branding" before preview/PDF.
      document: {
        schemaVersion: '1.0',
        format: input.format,
        meta: {
          topic: input.topic,
          audience: input.audience,
          offer: input.offer,
          tone: input.tone,
          length: input.length,
          language: input.language,
        },
        title,
        subtitle: cut(data.subtitle, 160),
        sections,
        cta: {
          heading: cut(cta.heading, 90),
          text: cut(cta.text, 400),
          buttonLabel: cut(cta.buttonLabel, 40),
          url: '',
        },
      },
      generator: {
        promptVersion: settings.promptVersion,
        model: res.model || settings.model,
        tokens: res.usage ? res.usage.total_tokens : null,
      },
    },
  },
}];

// Adds a fresh writing pass to the answer when one was issued.
const r = $input.first().json.response;
const g = $('Guard').first().json;
if (r && r.ok && g.newPass) r.pass = g.newPass;
return [{ json: { statusCode: 200, response: r } }];

// ===================== SETTINGS (safe to change) =====================
const PROMPT_VERSION = 'v2';          // which prompt file to use: section.v2.md
const MODEL = 'gpt-4.1-mini';         // OpenAI model used to write sections
const REPO_RAW = 'https://raw.githubusercontent.com/mysteriouslyscentedtyrant/lead-magnet-generator/main';
// =====================================================================

// The page sends { document, sectionId }. "document" is the approved outline
// (written blocks and branding, if present, are ignored). The user may have
// edited the outline, so everything is checked again here.

const FORMATS = ['ebook', 'guide', 'checklist'];
const TONES = ['friendly', 'professional', 'bold', 'inspiring', 'conversational'];
const LENGTHS = ['short', 'standard', 'detailed'];
const RULES = {
  ebook:     { first: ['intro'],   middle: 'chapter', last: ['conclusion'],            min: 4, max: 7 },
  guide:     { first: ['problem'], middle: 'step',    last: ['mistakes', 'next_step'], min: 3, max: 9 },
  checklist: { first: [],          middle: 'group',   last: [],                        min: 3, max: 5 },
};

const body = $('Guard').first().json.body || {};
const doc = body.document && typeof body.document === 'object' ? body.document : {};
const meta = doc.meta && typeof doc.meta === 'object' ? doc.meta : {};
const errors = [];

// Same cleaning as the outline workflow: no control/invisible characters,
// no angle brackets (can't break the prompt tags), no {{ }} (no placeholder injection).
function clean(value) {
  if (typeof value !== 'string') return '';
  return value
    .normalize('NFKC')
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u2069\uFEFF]/g, ' ')
    .replace(/[<>]/g, ' ')
    .replace(/\{\{|\}\}/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function text(value, label, min, max) {
  const v = clean(value);
  if (v.length < min) errors.push(`${label} must be at least ${min} characters.`);
  else if (v.length > max) errors.push(`${label} must be ${max} characters or less.`);
  return v;
}
function choice(value, label, allowed, fallback) {
  if ((value === undefined || value === null || value === '') && fallback !== undefined) return fallback;
  const v = String(value == null ? '' : value).trim().toLowerCase();
  if (!allowed.includes(v)) { errors.push(`${label} must be one of: ${allowed.join(', ')}.`); return ''; }
  return v;
}

const format = choice(doc.format, 'Format', FORMATS);
const topic = text(meta.topic, 'Topic', 3, 200);
const audience = text(meta.audience, 'Audience', 3, 400);
const offer = text(meta.offer || '', 'Offer', 0, 300);
const tone = choice(meta.tone, 'Tone', TONES, 'friendly');
const length = choice(meta.length, 'Length', LENGTHS, 'standard');
let language = clean(meta.language || '') || 'English';
if (!/^[\p{L} ()-]{2,30}$/u.test(language)) errors.push('Language must be a language name such as English or French.');

const title = text(doc.title, 'Title', 3, 90);
const subtitle = text(doc.subtitle || '', 'Subtitle', 0, 160);

const rawSections = Array.isArray(doc.sections) ? doc.sections : [];
if (rawSections.length < 1 || rawSections.length > 12) errors.push('The outline must have between 1 and 12 sections.');

const sections = rawSections.slice(0, 12).map((s, i) => {
  s = s && typeof s === 'object' ? s : {};
  const n = i + 1;
  const id = typeof s.id === 'string' && /^s[0-9]{1,2}$/.test(s.id) ? s.id : '';
  if (!id) errors.push(`Section ${n} has an invalid id.`);
  const keyPoints = Array.isArray(s.keyPoints) ? s.keyPoints : [];
  if (keyPoints.length > 8) errors.push(`Section ${n} has more than 8 key points.`);
  return {
    id,
    type: String(s.type || ''),
    heading: text(s.heading, `Section ${n} heading`, 2, 90),
    goal: text(s.goal || '', `Section ${n} goal`, 0, 200),
    keyPoints: keyPoints.slice(0, 8).map((k, j) => text(k, `Section ${n} key point ${j + 1}`, 1, 160)),
  };
});

const ids = sections.map(s => s.id);
if (new Set(ids).size !== ids.length) errors.push('Section ids must be unique.');

if (format) {
  const rule = RULES[format];
  const types = sections.map(s => s.type);
  const middle = types.length - rule.first.length - rule.last.length;
  const expected = [...rule.first, ...Array(Math.max(middle, 0)).fill(rule.middle), ...rule.last];
  if (middle < rule.min || middle > rule.max || types.join() !== expected.join()) {
    errors.push(`A ${format} needs ${rule.first.concat([`${rule.min}-${rule.max} x ${rule.middle}`], rule.last).join(', ')} sections in that order.`);
  }
}

const sectionId = typeof body.sectionId === 'string' ? body.sectionId : '';
const index = sections.findIndex(s => s.id === sectionId);
if (index === -1) errors.push('sectionId does not match any section in the outline.');

if (errors.length) {
  return [{ json: { ok: false, statusCode: 400, response: { ok: false, code: 'invalid_input', message: errors.slice(0, 5).join(' ') } } }];
}

const target = sections[index];
const outline = sections
  .map((s, i) => `${i + 1}. [${s.type}] ${s.heading}${i === index ? '   [THIS SECTION]' : ''}`)
  .join('\n');

return [{
  json: {
    ok: true,
    format,
    sectionId,
    sectionType: target.type,
    length,
    model: MODEL,
    promptVersion: PROMPT_VERSION,
    promptUrl: `${REPO_RAW}/prompts/section.${PROMPT_VERSION}.md`,
    schemaUrl: `${REPO_RAW}/schema/section.response.schema.json`,
    vars: {
      format, title, subtitle, audience,
      offer: offer || 'Not provided',
      tone, length, language,
      outline,
      position: `${index + 1} of ${sections.length}`,
      section_type: target.type,
      section_heading: target.heading,
      section_goal: target.goal || '(no goal given)',
      section_key_points: target.keyPoints.length ? target.keyPoints.map(k => '- ' + k).join('\n') : '- (no key points given: cover the heading)',
    },
  },
}];

// Builds the OpenAI request from the section prompt and response schema loaded from GitHub.
const settings = $('Validate section input').first().json;
const promptText = String($('Load section prompt').first().json.data || '').replace(/\r\n/g, '\n');
const schemaText = $('Load section schema').first().json.data;

// Split the prompt file into its SYSTEM and USER parts.
const sysMarker = '===SYSTEM===';
const userMarker = '===USER===';
const sysAt = promptText.indexOf(sysMarker);
const userAt = promptText.indexOf(userMarker);
if (sysAt === -1 || userAt === -1 || userAt < sysAt) {
  throw new Error('Prompt file is missing the ===SYSTEM=== or ===USER=== marker: ' + settings.promptUrl);
}
const system = promptText.slice(sysAt + sysMarker.length, userAt).trim();
const userTemplate = promptText.slice(userAt + userMarker.length).trim();

// Fill {{placeholders}} in ONE pass, so text typed by a user is never re-read as a placeholder.
const vars = settings.vars;
const user = userTemplate.replace(/\{\{(\w+)\}\}/g, (match, key) => {
  if (!(key in vars)) throw new Error('Prompt uses an unknown placeholder: ' + match);
  return vars[key];
});

let responseSchema;
try {
  responseSchema = typeof schemaText === 'string' ? JSON.parse(schemaText) : schemaText;
} catch (e) {
  throw new Error('Response schema is not valid JSON: ' + settings.schemaUrl);
}

return [{
  json: {
    requestBody: {
      model: settings.model,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      response_format: { type: 'json_schema', json_schema: responseSchema },
      max_completion_tokens: 3500,
    },
  },
}];

// Checks the AI answer for ONE section and cleans every block.
// Any problem throws an error -> the workflow answers with a generic "please try again".
const settings = $('Validate section input').first().json;
const res = $input.first().json;

const choice = res.choices && res.choices[0];
const message = choice && choice.message;
if (!message) throw new Error('OpenAI returned no message: ' + JSON.stringify(res).slice(0, 500));
if (choice.finish_reason === 'length') throw new Error('Section was cut off (max_completion_tokens too low).');

if (message.refusal) {
  return [{ json: { response: { ok: false, code: 'rejected', sectionId: settings.sectionId,
    message: "We can't write this section. Please edit its heading or key points and try again." } } }];
}

let data;
try { data = JSON.parse(message.content); }
catch (e) { throw new Error('AI answer is not valid JSON: ' + String(message.content).slice(0, 500)); }

// ---------- text helpers ----------
const URL_RE = /\b(?:https?:\/\/|www\.)\S+/gi;
const EMAIL_RE = /\b[\w.+-]+@[\w-]+\.[\w.-]+\b/g;
function tidy(value) {
  return String(value == null ? '' : value)
    .replace(/[\u0000-\u001F\u007F-\u009F\u200B-\u200F\u2028-\u202E\u2060-\u2069\uFEFF]/g, ' ')
    .replace(URL_RE, '')
    .replace(EMAIL_RE, '')
    .replace(/\*\*|__|`/g, '')
    .replace(/^\s*#{1,6}\s+/, '')
    .replace(/\s+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .trim();
}
function cut(value, max) {
  const v = tidy(value);
  if (v.length <= max) return v;
  const short = v.slice(0, max);
  const space = short.lastIndexOf(' ');
  return (space > max * 0.6 ? short.slice(0, space) : short).replace(/[\s,;:-]+$/, '');
}
// List items: also drop leading bullets, numbers and checkboxes the design adds itself.
function item(value) {
  return cut(String(value == null ? '' : value).replace(/^\s*(\d+[.)](?=\s)|[-*\u2022\u2013](?=\s)|\[[ xX]?\]|\u2610|\u2611)\s*/, ''), 300);
}

const TEXT_TYPES = ['paragraph', 'subheading', 'tip', 'warning', 'example'];
const LIST_TYPES = ['bullets', 'steps', 'checklist'];

let blocks = (Array.isArray(data.blocks) ? data.blocks : []).map(b => {
  b = b && typeof b === 'object' ? b : {};
  const type = String(b.type || '');
  const items = (Array.isArray(b.items) ? b.items : []).map(item).filter(Boolean).slice(0, 15);
  if (TEXT_TYPES.includes(type)) {
    const t = cut(b.text, type === 'subheading' ? 90 : 1500);
    return t ? { type, text: t, items: [] } : null;
  }
  if (LIST_TYPES.includes(type)) {
    return items.length ? { type, text: cut(b.text, 300), items } : null;
  }
  if (type === 'template') {
    return items.length ? { type, text: cut(b.text, 120) || 'Template', items } : null;
  }
  return null;
}).filter(Boolean).slice(0, 30);

// A checklist group is exactly ONE checklist block of short items.
if (settings.sectionType === 'group') {
  const all = blocks.filter(b => b.type === 'checklist').flatMap(b => b.items);
  const seen = new Set();
  const unique = all
    .map(i => cut(i, 120))
    .filter(i => { const k = i.toLowerCase(); if (!i || seen.has(k)) return false; seen.add(k); return true; })
    .slice(0, 6);
  if (unique.length < 3) throw new Error('Checklist group has fewer than 3 items.');
  blocks = [{ type: 'checklist', text: '', items: unique }];
}

// Never start a section with a subheading only, never end on one.
while (blocks.length && blocks[blocks.length - 1].type === 'subheading') blocks.pop();
if (!blocks.length) throw new Error('Section has no usable content blocks.');

const words = blocks.reduce((n, b) => n + [b.text, ...b.items].join(' ').split(/\s+/).filter(Boolean).length, 0);

return [{
  json: {
    response: {
      ok: true,
      sectionId: settings.sectionId,
      blocks,
      generator: {
        promptVersion: settings.promptVersion,
        model: res.model || settings.model,
        tokens: res.usage ? res.usage.total_tokens : null,
        words,
      },
    },
  },
}];

// Adds a fresh writing pass to the answer when one was issued.
const r = $input.first().json.response;
const g = $('Guard').first().json;
if (r && r.ok && g.newPass) r.pass = g.newPass;
return [{ json: { statusCode: 200, response: r } }];
